CustomField.formula:
IF(ISPICKVAL( TSGCFG__Consolidation_Method__c , 'Average') && TSGCFG__WideTotalCPCColorLineItem__c > 0 ,
TSGCFG__WideSumofCPCColor2__c / TSGCFG__WideTotalCPCColorLineItem__c,
IF( ABS(TSGCFG__WideTotalColor2Volume__c-TSGCFG__WideTotalVolumeIncludesColor2__c)<>0, TSGCFG__WideTotalColor2MonthlyCost__c / ABS(TSGCFG__WideTotalColor2Volume__c-TSGCFG__WideTotalVolumeIncludesColor2__c),
IF( TSGCFG__WideTotalCPCColorLineItem__c > 0, TSGCFG__WideSumofCPCColor2__c / TSGCFG__WideTotalCPCColorLineItem__c, 0
)
)
)
